1	/**
2	 * Feature Notification Watcher — detects feature-level lifecycle events and
3	 * routes them to the NotificationPort.
4	 *
5	 * Called once per poll cycle (after syncWorkspaces). Tracks per-process state
6	 * so it can distinguish the "first active poll" (feature_start) from a
7	 * "status change" (feature_summary_changed).
8	 *
9	 * Guarantees:
10	 * - Calls postFeatureMessage('feature_start', ...) exactly once per
11	 *   process run per feature the first time it is seen in an active state.
12	 *   ensureFeatureThread is idempotent via Redis so restart re-entry is safe.
13	 * - Calls postFeatureMessage('feature_summary_changed', ...) only when
14	 *   feature_status or next_action changes after the initial start.
15	 * - Never calls the port on a routine poll with no change.
16	 * - Never calls postFeatureMessage for task-only transitions (it only reads
17	 *   feature-level fields from status.yaml).
18	 * - Skips terminal features (done, cancelled).
19	 */
20	
21	import { existsSync, readdirSync, readFileSync } from "node:fs";
22	import { execSync } from "node:child_process";
23	import { join } from "node:path";
24	import { parse as parseYaml } from "yaml";
25	import type { NotificationPort } from "../notifications/notification.port.js";
26	import type { FeatureContext } from "../notifications/notification.types.js";
27	import { featuresRoot, featureBranchName, statusYamlRelPath, TASKS_DIR } from "../paths.js";
28	import { buildGitEnv } from "../git-env.js";
29	
30	// ── Types ─────────────────────────────────────────────────────────────────────
31	
32	export interface FeatureNotificationState {
33	  /** Features for which feature_start has been dispatched in this process run. */
34	  startedFeatures: Set<string>;
35	  /** Last seen compound status key per featureId: "<feature_status>|<next_action>". */
36	  lastStatusKeys: Map<string, string>;
37	}
38	
39	export function createFeatureNotificationState(): FeatureNotificationState {
40	  return {
41	    startedFeatures: new Set(),
42	    lastStatusKeys: new Map(),
43	  };
44	}
45	
46	export interface RunFeatureNotificationOpts {
47	  workspaceRoot: string;
48	  workspaceId: string;
49	  notificationPort: NotificationPort;
50	  state: FeatureNotificationState;
51	  gitAuthorEmail?: string;
52	  gitAuthorName?: string;
53	  sshKeyPath?: string;
54	  emit: (event: Record<string, unknown>) => void;
55	}
56	
57	// ── Status YAML shape ──────────────────────────────────────────────────────────
58	
59	interface StatusYaml {
60	  title?: string;
61	  feature_status?: string;
62	  next_action?: string | null;
63	  handoff_pr_url?: string | null;
64	  workspace_feature_pr_url?: string | null;
65	  feature_branch?: string | null;
66	  history?: Array<{ at?: string }>;
67	  [key: string]: unknown;
68	}
69	
70	// ── Internal constants ────────────────────────────────────────────────────────
71	
72	const ACTIVE_STATUSES = new Set([
73	  "ready_for_implementation",
74	  "in_implementation",
75	]);
76	
77	const TERMINAL_STATUSES = new Set(["done", "cancelled"]);
78	
79	// The watcher handles feature_summary_changed for transitions to in_handoff
80	// as well (the handoff_submitted trigger is fired separately in
81	// check-feature-tasks-done). This avoids a notification gap for features
82	// that transition in_handoff without the watcher having fired handoff_submitted.
83	const WATCHED_STATUSES = new Set([
84	  "ready_for_implementation",
85	  "in_implementation",
86	  "in_handoff",
87	]);
88	
89	// ── Helpers ───────────────────────────────────────────────────────────────────
90	
91	function listFeatureIds(workspaceRoot: string): string[] {
92	  const root = featuresRoot(workspaceRoot);
93	  if (!existsSync(root)) return [];
94	  try {
95	    return readdirSync(root, { withFileTypes: true })
96	      .filter((e) => e.isDirectory())
97	      .map((e) => e.name);
98	  } catch {
99	    return [];
100	  }
101	}
102	
103	/**
104	 * Read status.yaml for a feature from origin/<featureBranch>, falling back to
105	 * origin/baseBranch then local FS. Returns null when unreadable.
106	 */
107	function readStatusYaml(
108	  workspaceRoot: string,
109	  featureId: string,
110	  env: NodeJS.ProcessEnv,
111	): StatusYaml | null {
112	  const featureBranch = featureBranchName(featureId);
113	  const relPath = statusYamlRelPath(featureId);
114	
115	  for (const ref of [`origin/${featureBranch}`, "origin/main"]) {
116	    try {
117	      const raw = execSync(
118	        `git -C "${workspaceRoot}" show "${ref}:${relPath}"`,
119	        { encoding: "utf-8", stdio: "pipe" },
120	      );
121	      const parsed = parseYaml(raw) as StatusYaml | undefined;
122	      if (parsed && typeof parsed === "object") return parsed;
123	    } catch { /* try next ref */ }
124	  }
125	
126	  const absPath = join(workspaceRoot, "docs", "features", featureId, "status.yaml");
127	  if (!existsSync(absPath)) return null;
128	  try {
129	    return parseYaml(readFileSync(absPath, "utf-8")) as StatusYaml;
130	  } catch {
131	    return null;
132	  }
133	}
134	
135	/**
136	 * Count task YAML files for a feature from origin/<featureBranch>.
137	 * Returns 0 when unreachable.
138	 */
139	function countTaskFiles(
140	  workspaceRoot: string,
141	  featureId: string,
142	  env: NodeJS.ProcessEnv,
143	): number {
144	  const featureBranch = featureBranchName(featureId);
145	  const tasksRelDir = join("docs", "features", featureId, TASKS_DIR);
146	  try {
147	    const listing = execSync(
148	      `git -C "${workspaceRoot}" ls-tree --name-only "origin/${featureBranch}" "${tasksRelDir}/"`,
149	      { encoding: "utf-8", stdio: "pipe" },
150	    );
151	    return listing
152	      .split("\n")
153	      .map((f) => f.trim())
154	      .filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
155	  } catch {
156	    // Feature branch may not exist yet — fall back to local FS count
157	    const dir = join(workspaceRoot, "docs", "features", featureId, TASKS_DIR);
158	    if (!existsSync(dir)) return 0;
159	    try {
160	      return readdirSync(dir).filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
161	    } catch {
162	      return 0;
163	    }
164	  }
165	}
166	
167	function buildFeatureContext(
168	  statusYaml: StatusYaml,
169	  totalTaskCount: number,
170	): FeatureContext {
171	  const history = statusYaml.history ?? [];
172	  const lastEntry = history[history.length - 1];
173	  return {
174	    title: statusYaml.title ?? "Untitled feature",
175	    status: statusYaml.feature_status ?? "unknown",
176	    nextAction: statusYaml.next_action ?? null,
177	    handoff: statusYaml.handoff_pr_url ?? null,
178	    featurePr: statusYaml.workspace_feature_pr_url ?? null,
179	    totalTaskCount,
180	    lastUpdatedAt: lastEntry?.at ?? null,
181	  };
182	}
183	
184	/** Compound status key that captures all feature-level fields we watch. */
185	function statusKey(s: StatusYaml): string {
186	  return `${s.feature_status ?? ""}|${s.next_action ?? ""}`;
187	}
188	
189	// ── Public API ────────────────────────────────────────────────────────────────
190	
191	/**
192	 * One poll cycle of feature notification detection.
193	 *
194	 * Non-throwing: errors per-feature are emitted and the scan continues.
195	 */
196	export async function runFeatureNotificationStep(
197	  opts: RunFeatureNotificationOpts,
198	): Promise<void> {
199	  const {
200	    workspaceRoot,
201	    workspaceId,
202	    notificationPort,
203	    state,
204	    gitAuthorEmail = "coder@workflow",
205	    gitAuthorName = gitAuthorEmail,
206	    sshKeyPath,
207	    emit,
208	  } = opts;
209	
210	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
211	
212	  const featureIds = listFeatureIds(workspaceRoot);
213	
214	  for (const featureId of featureIds) {
215	    try {
216	      const statusYaml = readStatusYaml(workspaceRoot, featureId, env);
217	      if (!statusYaml) continue;
218	
219	      const featureStatus = statusYaml.feature_status ?? "";
220	
221	      // Skip terminal features entirely.
222	      if (TERMINAL_STATUSES.has(featureStatus)) continue;
223	
224	      // Only watch features in known active states.
225	      if (!WATCHED_STATUSES.has(featureStatus)) continue;
226	
227	      const totalTaskCount = countTaskFiles(workspaceRoot, featureId, env);
228	      const context = buildFeatureContext(statusYaml, totalTaskCount);
229	      const currentKey = statusKey(statusYaml);
230	
231	      if (!state.startedFeatures.has(featureId)) {
232	        // First time we observe this feature as active — send feature_start.
233	        // Only do this for truly active (not in_handoff) features so that a
234	        // process restart after handoff doesn't re-trigger start.
235	        if (ACTIVE_STATUSES.has(featureStatus)) {
236	          emit({ type: "feature_notification_start", feature_id: featureId });
237	          await notificationPort.postFeatureMessage(featureId, "feature_start", context);
238	          state.startedFeatures.add(featureId);
239	          state.lastStatusKeys.set(featureId, currentKey);
240	        } else {
241	          // in_handoff and not previously started — still record as seen.
242	          state.startedFeatures.add(featureId);
243	          state.lastStatusKeys.set(featureId, currentKey);
244	        }
245	      } else {
246	        // Feature already seen — check if status changed.
247	        const lastKey = state.lastStatusKeys.get(featureId);
248	        if (lastKey !== currentKey) {
249	          emit({
250	            type: "feature_notification_summary_changed",
251	            feature_id: featureId,
252	            prev_status: lastKey ?? "",
253	            new_status: currentKey,
254	          });
255	          await notificationPort.postFeatureMessage(
256	            featureId,
257	            "feature_summary_changed",
258	            context,
259	          );
260	          state.lastStatusKeys.set(featureId, currentKey);
261	        }
262	        // No change — routine poll, no port call.
263	      }
264	    } catch (e) {
265	      emit({
266	        type: "feature_notification_watcher_error",
267	        feature_id: featureId,
268	        details: String(e),
269	      });
270	    }
271	  }
272	}
