1	/**
2	 * Tests for feature-notification-watcher.ts
3	 *
4	 * Test matrix:
5	 *  1. feature_start called on first active poll for a ready_for_implementation feature.
6	 *  2. feature_start called on first active poll for an in_implementation feature.
7	 *  3. No call on routine poll when nothing changed.
8	 *  4. feature_summary_changed called after feature_status changes.
9	 *  5. feature_summary_changed called after next_action changes (same status).
10	 *  6. No call on task-only transition (feature_status and next_action unchanged).
11	 *  7. Already-done feature: no feature_start, no feature_summary_changed.
12	 *  8. Already-cancelled feature: skipped entirely.
13	 *  9. feature_start not called for in_handoff feature on first sight (not active).
14	 * 10. feature_summary_changed called when status changes from active to in_handoff.
15	 * 11. Multiple features in one workspace — each tracked independently.
16	 * 12. git show fails for a feature — error emitted, other features unaffected.
17	 * 13. NotificationPort throws — error caught, emitted, loop continues.
18	 */
19	
20	import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
21	import {
22	  mkdtempSync,
23	  mkdirSync,
24	  writeFileSync,
25	  rmSync,
26	} from "node:fs";
27	import { tmpdir } from "node:os";
28	import { join } from "node:path";
29	import { stringify as yamlStringify } from "yaml";
30	import {
31	  createFeatureNotificationState,
32	  runFeatureNotificationStep,
33	} from "../src/feature-branch/feature-notification-watcher.js";
34	import type { NotificationPort } from "../src/notifications/notification.port.js";
35	
36	// ── Mocks ─────────────────────────────────────────────────────────────────────
37	
38	vi.mock("node:child_process", async (importOriginal) => {
39	  const actual = await importOriginal<typeof import("node:child_process")>();
40	  return { ...actual, execSync: vi.fn() };
41	});
42	
43	import { execSync } from "node:child_process";
44	const mockExecSync = vi.mocked(execSync);
45	
46	// ── Mock NotificationPort builder ─────────────────────────────────────────────
47	
48	function makeMockPort(): NotificationPort & {
49	  postFeatureMessage: ReturnType<typeof vi.fn>;
50	  closeFeatureThread: ReturnType<typeof vi.fn>;
51	  postTaskMessage: ReturnType<typeof vi.fn>;
52	  closeTaskThread: ReturnType<typeof vi.fn>;
53	} {
54	  return {
55	    postFeatureMessage: vi.fn().mockResolvedValue(undefined),
56	    closeFeatureThread: vi.fn().mockResolvedValue(undefined),
57	    postTaskMessage: vi.fn().mockResolvedValue(undefined),
58	    closeTaskThread: vi.fn().mockResolvedValue(undefined),
59	  };
60	}
61	
62	// ── Fixtures ──────────────────────────────────────────────────────────────────
63	
64	const WORKSPACE_ID = "ws-test";
65	
66	const tmpDirs: string[] = [];
67	
68	function makeTmpWorkspace(): string {
69	  const dir = mkdtempSync(join(tmpdir(), "feat-notify-watcher-"));
70	  tmpDirs.push(dir);
71	  return dir;
72	}
73	
74	function makeStatusYaml(overrides: Record<string, unknown> = {}): Record<string, unknown> {
75	  return {
76	    title: "My Feature",
77	    feature_status: "ready_for_implementation",
78	    next_action: "Claim T1.",
79	    handoff_pr_url: null,
80	    workspace_feature_pr_url: null,
81	    history: [{ at: "2026-05-23T10:00:00Z", by: "bot@example.com", action: "feature_created" }],
82	    ...overrides,
83	  };
84	}
85	
86	/**
87	 * Set up mock so execSync returns the given status yaml for the feature branch
88	 * lookup, and an empty listing for ls-tree (0 task files).
89	 */
90	function setupGitMock(featureId: string, statusYaml: Record<string, unknown>): void {
91	  mockExecSync.mockImplementation((cmd: string) => {
92	    const cmdStr = String(cmd);
93	    if (cmdStr.includes("show") && cmdStr.includes("status.yaml")) {
94	      return yamlStringify(statusYaml);
95	    }
96	    if (cmdStr.includes("ls-tree")) {
97	      return ""; // no task files
98	    }
99	    return "";
100	  });
101	}
102	
103	/**
104	 * Set up mock to simulate execSync throwing for git show (feature branch absent).
105	 */
106	function setupGitMockThrows(): void {
107	  mockExecSync.mockImplementation((cmd: string) => {
108	    if (String(cmd).includes("show")) throw new Error("git show failed");
109	    return "";
110	  });
111	}
112	
113	// ── Suite ─────────────────────────────────────────────────────────────────────
114	
115	afterEach(() => {
116	  for (const dir of tmpDirs) {
117	    try { rmSync(dir, { recursive: true, force: true }); } catch { /* best-effort */ }
118	  }
119	  tmpDirs.length = 0;
120	  vi.clearAllMocks();
121	});
122	
123	describe("runFeatureNotificationStep", () => {
124	  // ── Test 1 ─────────────────────────────────────────────────────────────────
125	  it("calls postFeatureMessage(feature_start) on first active poll for ready_for_implementation", async () => {
126	    const wsRoot = makeTmpWorkspace();
127	    const featureId = "my-feature";
128	    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
129	    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");
130	
131	    const statusYaml = makeStatusYaml({ feature_status: "ready_for_implementation" });
