/**
 * Tests for feature-notification-watcher.ts
 *
 * Test matrix:
 *  1. feature_start called on first active poll for a ready_for_implementation feature.
 *  2. feature_start called on first active poll for an in_implementation feature.
 *  3. No call on routine poll when nothing changed.
 *  4. feature_summary_changed called after feature_status changes.
 *  5. feature_summary_changed called after next_action changes (same status).
 *  6. No call on task-only transition (feature_status and next_action unchanged).
 *  7. Already-done feature: no feature_start, no feature_summary_changed.
 *  8. Already-cancelled feature: skipped entirely.
 *  9. feature_start not called for in_handoff feature on first sight (not active).
 * 10. feature_summary_changed called when status changes from active to in_handoff.
 * 11. Multiple features in one workspace — each tracked independently.
 * 12. git show fails for a feature — error emitted, other features unaffected.
 * 13. NotificationPort throws — error caught, emitted, loop continues.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify } from "yaml";
import {
  createFeatureNotificationState,
  runFeatureNotificationStep,
} from "../src/feature-branch/feature-notification-watcher.js";
import type { NotificationPort } from "../src/notifications/notification.port.js";

// ── Mocks ─────────────────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn() };
});

import { execSync } from "node:child_process";
const mockExecSync = vi.mocked(execSync);

// ── Mock NotificationPort builder ─────────────────────────────────────────────

function makeMockPort(): NotificationPort & {
  postFeatureMessage: ReturnType<typeof vi.fn>;
  closeFeatureThread: ReturnType<typeof vi.fn>;
  postTaskMessage: ReturnType<typeof vi.fn>;
  closeTaskThread: ReturnType<typeof vi.fn>;
} {
  return {
    postFeatureMessage: vi.fn().mockResolvedValue(undefined),
    closeFeatureThread: vi.fn().mockResolvedValue(undefined),
    postTaskMessage: vi.fn().mockResolvedValue(undefined),
    closeTaskThread: vi.fn().mockResolvedValue(undefined),
  };
}

// ── Fixtures ──────────────────────────────────────────────────────────────────

const WORKSPACE_ID = "ws-test";

const tmpDirs: string[] = [];

function makeTmpWorkspace(): string {
  const dir = mkdtempSync(join(tmpdir(), "feat-notify-watcher-"));
  tmpDirs.push(dir);
  return dir;
}

function makeStatusYaml(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    title: "My Feature",
    feature_status: "ready_for_implementation",
    next_action: "Claim T1.",
    handoff_pr_url: null,
    workspace_feature_pr_url: null,
    history: [{ at: "2026-05-23T10:00:00Z", by: "bot@example.com", action: "feature_created" }],
    ...overrides,
  };
}

/**
 * Set up mock so execSync returns the given status yaml for the feature branch
 * lookup, and an empty listing for ls-tree (0 task files).
 */
function setupGitMock(featureId: string, statusYaml: Record<string, unknown>): void {
  mockExecSync.mockImplementation((cmd: string) => {
    const cmdStr = String(cmd);
    if (cmdStr.includes("show") && cmdStr.includes("status.yaml")) {
      return yamlStringify(statusYaml);
    }
    if (cmdStr.includes("ls-tree")) {
      return ""; // no task files
    }
    return "";
  });
}

/**
 * Set up mock to simulate execSync throwing for git show (feature branch absent).
 */
function setupGitMockThrows(): void {
  mockExecSync.mockImplementation((cmd: string) => {
    if (String(cmd).includes("show")) throw new Error("git show failed");
    return "";
  });
}

// ── Suite ─────────────────────────────────────────────────────────────────────

afterEach(() => {
  for (const dir of tmpDirs) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  tmpDirs.length = 0;
  vi.clearAllMocks();
});

describe("runFeatureNotificationStep", () => {
  // ── Test 1 ─────────────────────────────────────────────────────────────────
  it("calls postFeatureMessage(feature_start) on first active poll for ready_for_implementation", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const statusYaml = makeStatusYaml({ feature_status: "ready_for_implementation" });
    setupGitMock(featureId, statusYaml);

    const port = makeMockPort();
    const state = createFeatureNotificationState();
    const events: Record<string, unknown>[] = [];

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot,
      workspaceId: WORKSPACE_ID,
      notificationPort: port,
      state,
      emit: (e) => events.push(e),
    });

    expect(port.postFeatureMessage).toHaveBeenCalledOnce();
    expect(port.postFeatureMessage).toHaveBeenCalledWith(
      featureId,
      "feature_start",
      expect.objectContaining({ status: "ready_for_implementation" }),
    );
    expect(state.startedFeatures.has(featureId)).toBe(true);
  });

  // ── Test 2 ─────────────────────────────────────────────────────────────────
  it("calls postFeatureMessage(feature_start) on first active poll for in_implementation", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation" }));

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot,
      workspaceId: WORKSPACE_ID,
      notificationPort: port,
      state,
      emit: () => {},
    });

    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureId, "feature_start", expect.any(Object));
  });

  // ── Test 3 ─────────────────────────────────────────────────────────────────
  it("makes no port call on routine poll when nothing changed", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const statusYaml = makeStatusYaml({ feature_status: "in_implementation" });
    setupGitMock(featureId, statusYaml);

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    // First poll: feature_start dispatched
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot,
      workspaceId: WORKSPACE_ID,
      notificationPort: port,
      state,
      emit: () => {},
    });
    expect(port.postFeatureMessage).toHaveBeenCalledOnce();

    port.postFeatureMessage.mockClear();

    // Second poll with same status: no call
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot,
      workspaceId: WORKSPACE_ID,
      notificationPort: port,
      state,
      emit: () => {},
    });

    expect(port.postFeatureMessage).not.toHaveBeenCalled();
  });

  // ── Test 4 ─────────────────────────────────────────────────────────────────
  it("calls postFeatureMessage(feature_summary_changed) after feature_status changes", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const port = makeMockPort();
    const state = createFeatureNotificationState();
    const emit = vi.fn();

    // First poll: ready_for_implementation
    setupGitMock(featureId, makeStatusYaml({ feature_status: "ready_for_implementation" }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit,
    });
    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureId, "feature_start", expect.any(Object));
    port.postFeatureMessage.mockClear();

    // Second poll: status changed to in_implementation
    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation" }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit,
    });

    expect(port.postFeatureMessage).toHaveBeenCalledOnce();
    expect(port.postFeatureMessage).toHaveBeenCalledWith(
      featureId,
      "feature_summary_changed",
      expect.objectContaining({ status: "in_implementation" }),
    );
  });

  // ── Test 5 ─────────────────────────────────────────────────────────────────
  it("calls feature_summary_changed when next_action changes (same status)", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation", next_action: "Claim T1." }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });
    port.postFeatureMessage.mockClear();

    // next_action changed
    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation", next_action: "Claim T2." }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureId, "feature_summary_changed", expect.any(Object));
  });

  // ── Test 6 ─────────────────────────────────────────────────────────────────
  it("makes no call when only tasks changed (feature status/next_action unchanged)", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const port = makeMockPort();
    const state = createFeatureNotificationState();
    const statusYaml = makeStatusYaml({ feature_status: "in_implementation", next_action: "Claim T3." });

    setupGitMock(featureId, statusYaml);
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });
    port.postFeatureMessage.mockClear();

    // Same feature_status and next_action — simulate task change by not changing statusYaml
    setupGitMock(featureId, statusYaml);
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).not.toHaveBeenCalled();
  });

  // ── Test 7 ─────────────────────────────────────────────────────────────────
  it("skips done features entirely — no port calls", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "done-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    setupGitMock(featureId, makeStatusYaml({ feature_status: "done" }));

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).not.toHaveBeenCalled();
  });

  // ── Test 8 ─────────────────────────────────────────────────────────────────
  it("skips cancelled features entirely — no port calls", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "cancelled-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    setupGitMock(featureId, makeStatusYaml({ feature_status: "cancelled" }));

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).not.toHaveBeenCalled();
  });

  // ── Test 9 ─────────────────────────────────────────────────────────────────
  it("does NOT call feature_start for in_handoff on first sight", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "handoff-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_handoff" }));

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    // in_handoff is not an ACTIVE state — feature_start must not be sent
    expect(port.postFeatureMessage).not.toHaveBeenCalled();
    // But the feature should still be recorded so future status changes emit summary_changed
    expect(state.startedFeatures.has(featureId)).toBe(true);
  });

  // ── Test 10 ────────────────────────────────────────────────────────────────
  it("calls feature_summary_changed when status changes from active to in_handoff", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    // First poll: active
    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation" }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });
    port.postFeatureMessage.mockClear();

    // Second poll: in_handoff
    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_handoff" }));
    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureId, "feature_summary_changed", expect.any(Object));
  });

  // ── Test 11 ────────────────────────────────────────────────────────────────
  it("tracks multiple features independently", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureA = "feature-alpha";
    const featureB = "feature-beta";
    mkdirSync(join(wsRoot, "docs", "features", featureA), { recursive: true });
    mkdirSync(join(wsRoot, "docs", "features", featureB), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureA, "status.yaml"), "");
    writeFileSync(join(wsRoot, "docs", "features", featureB, "status.yaml"), "");

    const statusA = makeStatusYaml({ feature_status: "ready_for_implementation" });
    const statusB = makeStatusYaml({ feature_status: "in_implementation" });

    mockExecSync.mockImplementation((cmd: string) => {
      const cmdStr = String(cmd);
      if (cmdStr.includes("show") && cmdStr.includes("status.yaml")) {
        if (cmdStr.includes(featureA)) return yamlStringify(statusA);
        if (cmdStr.includes(featureB)) return yamlStringify(statusB);
      }
      if (cmdStr.includes("ls-tree")) return "";
      return "";
    });

    const port = makeMockPort();
    const state = createFeatureNotificationState();

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: () => {},
    });

    expect(port.postFeatureMessage).toHaveBeenCalledTimes(2);
    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureA, "feature_start", expect.any(Object));
    expect(port.postFeatureMessage).toHaveBeenCalledWith(featureB, "feature_start", expect.any(Object));
    expect(state.startedFeatures.has(featureA)).toBe(true);
    expect(state.startedFeatures.has(featureB)).toBe(true);
  });

  // ── Test 12 ────────────────────────────────────────────────────────────────
  it("continues for other features when one feature's status.yaml is unreadable", async () => {
    const wsRoot = makeTmpWorkspace();
    const failFeature = "bad-feature";
    const goodFeature = "good-feature";
    mkdirSync(join(wsRoot, "docs", "features", failFeature), { recursive: true });
    mkdirSync(join(wsRoot, "docs", "features", goodFeature), { recursive: true });
    // failFeature has no status.yaml on FS — both git show and FS fallback will return null
    // goodFeature has a valid status.yaml via git show
    writeFileSync(join(wsRoot, "docs", "features", goodFeature, "status.yaml"), "");

    mockExecSync.mockImplementation((cmd: string) => {
      const cmdStr = String(cmd);
      if (cmdStr.includes("show") && cmdStr.includes(failFeature)) {
        throw new Error("git show: not found");
      }
      if (cmdStr.includes("show") && cmdStr.includes("status.yaml")) {
        return yamlStringify(makeStatusYaml({ feature_status: "in_implementation" }));
      }
      if (cmdStr.includes("ls-tree")) return "";
      return "";
    });

    const port = makeMockPort();
    const state = createFeatureNotificationState();
    const events: Record<string, unknown>[] = [];

    await runFeatureNotificationStep({
      workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: (e) => events.push(e),
    });

    // good-feature should still be processed despite bad-feature being unreadable
    expect(port.postFeatureMessage).toHaveBeenCalledWith(goodFeature, "feature_start", expect.any(Object));
    // bad-feature was skipped silently (null status from all sources)
    expect(port.postFeatureMessage).not.toHaveBeenCalledWith(failFeature, expect.any(String), expect.any(Object));
  });

  // ── Test 13 ────────────────────────────────────────────────────────────────
  it("emits error and continues when NotificationPort throws", async () => {
    const wsRoot = makeTmpWorkspace();
    const featureId = "my-feature";
    mkdirSync(join(wsRoot, "docs", "features", featureId), { recursive: true });
    writeFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "");

    setupGitMock(featureId, makeStatusYaml({ feature_status: "in_implementation" }));

    const port = makeMockPort();
    port.postFeatureMessage.mockRejectedValueOnce(new Error("Slack API error"));

    const state = createFeatureNotificationState();
    const events: Record<string, unknown>[] = [];

    await expect(
      runFeatureNotificationStep({
        workspaceRoot: wsRoot, workspaceId: WORKSPACE_ID, notificationPort: port, state, emit: (e) => events.push(e),
      }),
    ).resolves.toBeUndefined();

    const errorEvents = events.filter((e) => e["type"] === "feature_notification_watcher_error");
    expect(errorEvents.length).toBeGreaterThan(0);
  });
});

