83	  // Prefer the feature branch — this is where orchestrator writes in_handoff.
84	  for (const ref of [`origin/${featureBranch}`, "origin/main"]) {
85	    try {
86	      const raw = execSync(
87	        `git -C "${workspaceRoot}" show "${ref}:${relPath}"`,
88	        { encoding: "utf-8", stdio: "pipe" },
89	      );
90	      const parsed = parseYaml(raw) as StatusYaml | undefined;
91	      if (parsed && typeof parsed === "object") return parsed;
