149	/**
150	 * Check all features in the workspace. For any feature where all tasks are
151	 * done/cancelled and the handoff has not yet been triggered, fire the Handoff
152	 * Trigger.
153	 *
154	 * Non-throwing: each feature is processed independently.
155	 */
156	export async function checkFeatureTasksDone(
157	  opts: CheckFeatureTasksDoneOpts,
158	): Promise<void> {
159	  const {
160	    workspaceRoot,
161	    githubToken,
162	    gitAuthorEmail,
163	    gitAuthorName = gitAuthorEmail,
164	    sshKeyPath,
165	    notificationPort,
166	    workspaceId,
167	    emit,
168	  } = opts;
169	
170	  if (!githubToken) {
171	    emit({ type: "check_feature_tasks_done_skipped", reason: "no_github_token" });
172	    return;
173	  }
174	
175	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
176	
177	  // Fetch once so all git show calls see the latest remote state.
178	  try {
179	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
180	  } catch (e) {
181	    emit({ type: "check_feature_tasks_done_fetch_failed", details: String(e) });
182	    return;
183	  }
184	
185	  const featureIds = listFeatureIds(workspaceRoot);
186	
187	  for (const featureId of featureIds) {
188	    try {
189	      const featureBranch = featureBranchName(featureId);
190	      const statusYaml = readStatusFromBranch(workspaceRoot, featureId, featureBranch, env);
191	
192	      // Skip terminal or already-triggered features.
193	      const skip = ["in_handoff", "done", "cancelled"];
194	      if (skip.includes(statusYaml.feature_status ?? "")) continue;
195	      if (statusYaml.handoff_pr_url) continue;
196	
197	      const tasks = readTasksFromBranch(workspaceRoot, featureId, featureBranch, env);
198	      if (tasks.length === 0) continue;
199	
200	      const hasDone = tasks.some((t) => t.status === "done");
201	      const allTerminal = tasks.every(
202	        (t) => t.status === "done" || t.status === "cancelled",
203	      );
204	
205	      if (!hasDone || !allTerminal) continue;
206	
207	      emit({ type: "all_tasks_done", feature_id: featureId });
208	
209	      try {
210	        const { owner, repo, baseBranch } = parseManagementRepoCoords(workspaceRoot);
211	        const result = await fireHandoffTrigger({
212	          workspaceRoot,
213	          featureId,
214	          baseBranch,
215	          githubToken,
216	          repoOwner: owner,
217	          repoName: repo,
218	          gitAuthorEmail,
219	          gitAuthorName,
220	          sshKeyPath,
221	          emit,
222	        });
223	        if (result.error) {
224	          emit({ type: "handoff_trigger_failed", feature_id: featureId, details: result.error });
225	        } else if (notificationPort) {
226	          // Send handoff_submitted notification now that status.yaml has been
227	          // updated to in_handoff and the handoff PR URL is set.
228	          try {
229	            const history = statusYaml.history ?? [];
230	            const lastEntry = history[history.length - 1];
231	            await notificationPort.postFeatureMessage(featureId, "handoff_submitted", {
232	              title: statusYaml.title ?? "Untitled feature",
233	              status: "in_handoff",
234	              handoff: result.prUrl ?? null,
235	              featurePr: statusYaml.workspace_feature_pr_url ?? null,
236	              totalTaskCount: tasks.length,
237	              lastUpdatedAt: lastEntry?.at ?? null,
238	            });
239	          } catch (notifyErr) {
240	            emit({
241	              type: "handoff_submitted_notification_failed",
242	              feature_id: featureId,
243	              details: String(notifyErr),
244	            });
245	          }
246	        }
247	      } catch (e) {
248	        emit({ type: "handoff_trigger_failed", feature_id: featureId, details: String(e) });
249	      }
250	    } catch (e) {
251	      emit({ type: "check_feature_tasks_done_error", feature_id: featureId, details: String(e) });
252	    }
253	  }
254	}
