459	      // Fix dispatch → review-fixes mode + the specific review's URL.
460	      // Rebase dispatch → conflict-resolution mode (no review URL needed).
461	      ...(kind === "fix"    ? { MODE: "review-fixes",       ...(reviewUrl ? { REVIEW_URL: reviewUrl } : {}) } : {}),
462	      ...(kind === "rebase" ? { MODE: "conflict-resolution" } : {}),
463	    };
464	
465	    const adapter =
466	      runtimeProfile === "local-docker"
467	        ? new (await import("./adapters/executor/claude-docker-run.js")).ClaudeDockerRunAdapter({
468	            broker: ports.broker,
469	            extraEnv,
470	            workspacesDir: workspacesRoot,
471	          })
472	        : new SubProcessAdapter({
473	            broker: ports.broker,
474	            executorBinPath: resolvedExecutorBinPath,
475	            extraEnv,
476	            workspacesDir: workspacesRoot,
477	          });
478	
479	    return adapter.submit(execInput);
480	  }
