482	  // ── Sync workspaces + feature branch lifecycle ────────────────────────────
483	  async function syncWorkspaces(): Promise<{
484	    haltedUrls: Set<string>;
485	    failedFeatureBranchMap: Map<string, Set<string>>;
486	  }> {
487	    // Skip impl repo pulls while an executor is in-flight.
488	    // syncRepo does `checkout <baseBranch> && reset --hard origin/<baseBranch>`,
489	    // which would switch the shared working tree away from the task branch and
490	    // wipe any uncommitted edits the executor made in the impl repo.
491	    const inFlightCount = ports.broker.inFlightCount?.() ?? 0;
492	
493	    const pullResults = pullWorkspaces({
494	      watchUrls: config.watches,
495	      sshKeyPath,
496	      workspacesRoot,
497	      workflowUrl: process.env.WORKFLOW_URL,
498	      workflowLocalPath,
499	      emit,
500	      skipImplRepoPull: inFlightCount > 0,
501	    });
502	
503	    const haltedUrls = new Set(
504	      pullResults
505	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
506	        .map((r) => r.url),
507	    );
508	
509	    const failedFeatureBranchMap = new Map<string, Set<string>>();
510	    for (const watchUrl of config.watches) {
511	      if (haltedUrls.has(watchUrl)) continue;
512	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
513	      if (!existsSync(workspaceLocalPath)) continue;
514	      try {
515	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
516	        const failed = runFeatureBranchLifecycle({
517	          workspaceRoot: workspaceLocalPath,
518	          baseBranch: mgmtCoords.baseBranch,
519	          gitAuthorEmail,
520	          gitAuthorName,
521	          sshKeyPath,
522	          githubToken: githubToken || undefined,
523	          repoOwner: mgmtCoords.owner,
524	          repoName: mgmtCoords.repo,
525	          slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
526	          emit,
527	        });
528	        if (failed.size > 0) {
529	          failedFeatureBranchMap.set(workspaceLocalPath, failed);
530	          emit({ type: "feature_branch_lifecycle_blocked", workspace: watchUrl, failed_features: [...failed] });
531	        }
532	      } catch (e) {
533	        emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
534	      }
535	    }
536	
537	    return { haltedUrls, failedFeatureBranchMap };
538	  }
