540	  // ── Claim step: scan ready tasks, claim + spawn executor ─────────────────
541	  async function claimStep(
542	    haltedUrls: Set<string>,
543	    failedFeatureBranchMap: Map<string, Set<string>>,
544	  ): Promise<{ outcome: CycleOutcome; pulledWorkspaceRoots: string[] }> {
545	    const pulledWorkspaceRoots: string[] = [];
546	
547	    for (const watchUrl of config.watches) {
548	      if (haltedUrls.has(watchUrl)) continue;
549	
550	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
551	      pulledWorkspaceRoots.push(workspaceLocalPath);
552	
553	      if (!existsSync(workspaceLocalPath)) {
554	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
555	        continue;
556	      }
557	
558	      let eligibleTasks;
559	      try {
560	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
561	      } catch (e) {
562	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
563	        continue;
564	      }
565	
566	      if (eligibleTasks.length === 0) {
567	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
568	        continue;
569	      }
570	
571	      for (const { task, featureId } of eligibleTasks) {
572	        if (failedFeatureBranchMap.get(workspaceLocalPath)?.has(featureId)) {
573	          emit({ type: "task_skipped_feature_branch_failed", task_id: task.id, feature_id: featureId });
574	          continue;
575	        }
576	
577	        const claimResult = await claimTask({
578	          workspaceRoot: workspaceLocalPath,
579	          taskId: task.id,
580	          featureId,
581	          gitAuthorEmail,
582	          gitAuthorName,
583	          sshKeyPath,
584	          jitterMaxSeconds: config.jitter_max_seconds,
585	          // Task branches are seeded from and target the feature branch, not
586	          // the base branch — task PRs collect into the feature branch before
587	          // the Handoff Trigger merges the feature branch into the base.
588	          baseBranch: featureBranchName(featureId),
589	        });
590	
591	        const taskBranch = taskBranchName(featureId, task.id);
592	
593	        if (!claimResult.won) {
594	          if (claimResult.reason !== "branch_blocked_recovery") {
595	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
596	            continue;
597	          }
598	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
599	        } else {
600	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
601	        }
602	
603	        // ── Open management-repo PR ─────────────────────────────────────────
604	        if (githubToken) {
605	          try {
606	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
607	            await openWorkspacePr({
608	              workspaceRoot: workspaceLocalPath,
609	              featureId,
610	              taskId: task.id,
611	              branch: taskBranch,
612	              // Task PRs target the feature branch so all task changes collect
613	              // there before the Handoff Trigger merges to the base branch (T8).
614	              baseBranch: featureBranchName(featureId),
615	              githubToken,
616	              repoOwner: mgmtCoords.owner,
617	              repoName: mgmtCoords.repo,
618	              gitAuthorEmail,
619	              gitAuthorName,
620	              sshKeyPath,
621	            });
622	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
623	          } catch (e) {
624	            const stderr = (e as { stderr?: Buffer | string }).stderr;
625	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
626	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
627	          }
628	        }
629	
630	        // ── Resolve model + task repo ───────────────────────────────────────
631	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
632	          resolveTaskContext(workspaceLocalPath, featureId, task);
633	
634	        // ── RAG pre-flight ──────────────────────────────────────────────────
635	        const mcpRagUrl = process.env.MCP_RAG_URL;
636	        const workspaceYaml = parseYaml(
637	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
638	        ) as { workspace_id: string };
639	        const ragQuery = `${task.title} ${featureId}`;
640	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
641	
642	        try {
643	          writeRagPreFlight(
644	            workspaceLocalPath,
645	            featureId,
646	            task.id,
647	            taskBranch,
648	            gitAuthorEmail,
649	            gitAuthorName,
650	            sshKeyPath,
651	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
652	          );
653	        } catch (e) {
654	          const details = String(e);
655	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
656	          mutateTaskYaml({
657	            workspaceRoot: workspaceLocalPath,
658	            featureId,
659	            taskId: task.id,
660	            taskBranch,
661	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
662	            gitAuthorEmail,
663	            gitAuthorName,
664	            sshKeyPath,
665	          });
666	          continue;
667	        }
668	
669	
670	        // ── Submit executor (async — T6) ────────────────────────────────────
671	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
672	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
673	        const execHandle = await buildAndSubmitExecutor({
674	          task, featureId, workspaceId: workspaceYaml.workspace_id,
675	          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
676	          mgmtRepoUrl: mgmtCoords.repoUrl, implementationModel,
677	          resultPath, workspaceLocalPath,
678	        });
679	
680	        // Persist handle to task YAML for broker crash-recovery reconciliation.
681	        try {
682	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
683	        } catch (e) {
684	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
685	        }
686	
687	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
688	        if (runtimeProfile === "local-docker") dockerInFlight++;
689	        return { outcome: "ran_task", pulledWorkspaceRoots };
690	      }
691	    }
692	    return { outcome: "idle", pulledWorkspaceRoots };
693	  }
