696	  async function fixStep(haltedUrls: Set<string>): Promise<CycleOutcome> {
697	    for (const watchUrl of config.watches) {
698	      if (haltedUrls.has(watchUrl)) continue;
699	
700	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
701	      if (!existsSync(workspaceLocalPath)) continue;
702	
703	      let fixableTasks;
704	      try {
705	        fixableTasks = findFixableTasks(config, workspaceLocalPath);
706	      } catch (e) {
707	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
708	        continue;
709	      }
710	
711	      for (const { task, featureId } of fixableTasks) {
712	        const taskBranch = taskBranchName(featureId, task.id);
713	        const claimResult = await claimFixTask({
714	          workspaceRoot: workspaceLocalPath,
715	          taskId: task.id,
716	          featureId,
717	          gitAuthorEmail,
718	          gitAuthorName,
719	          sshKeyPath,
720	          jitterMaxSeconds: config.jitter_max_seconds,
721	        });
722	
723	        if (!claimResult.won) {
724	          emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason, details: claimResult.details });
725	          continue;
726	        }
727	
728	        emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
729	
730	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
731	        const fixWsYaml = parseYaml(
732	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
733	        ) as { workspace_id: string };
734	
735	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
736	        const prUrl = extractPrUrlFromTask(task);
737	        // Find the most recent reviewer_complete log entry and pull its
738	        // review_url out. The orchestrator persists review_url on
739	        // change_requested mutations (dispatch-review-result.ts) so the fix
740	        // agent can target THIS specific review's inline comments rather
741	        // than fetching "all unresolved threads on the PR" (lossy across
742	        // multiple review cycles).
743	        const lastReviewerComplete = [...task.log]
744	          .reverse()
745	          .find((e) => e.action === "reviewer_complete");
746	        const reviewUrl =
747	          typeof lastReviewerComplete?.review_url === "string"
748	            ? lastReviewerComplete.review_url
749	            : undefined;
750	        emit({ type: "fix_executor_dispatch_started", task_id: task.id, feature_id: featureId, pr_url: prUrl, review_url: reviewUrl });
751	        const fixMgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
752	        const fixHandle = await buildAndSubmitExecutor({
753	          task, featureId, workspaceId: fixWsYaml.workspace_id,
754	          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
755	          mgmtRepoUrl: fixMgmtCoords.repoUrl, implementationModel,
756	          resultPath, workspaceLocalPath,
757	          kind: "fix",
758	          prUrl: prUrl ?? undefined,
759	          reviewUrl,
760	        });
761	        emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
762	        if (runtimeProfile === "local-docker") dockerInFlight++;
763	        return "ran_task";
764	      }
765	    }
766	    return "idle";
767	  }
