769	  // ── PR poll step (5a): rebase conflicted PRs + handle merged PRs ──────────
770	  // Runs inside dispatchBlock so the subprocess guard prevents it from running
771	  // while an executor shares the container filesystem.
772	  async function prPollStep(pulledWorkspaceRoots: string[]): Promise<CycleOutcome> {
773	    let outcome: CycleOutcome = "idle";
774	    let prResults: PrStatusResult[] = [];
775	    try {
776	      ({ prResults } = await checkInReviewPrs({
777	        workspaceRoots: pulledWorkspaceRoots,
778	        githubToken,
779	        emit,
780	      }));
781	    } catch (e) {
782	      emit({ type: "in_review_poll_error", details: String(e) });
783	    }
784	
785	    for (const wsRoot of pulledWorkspaceRoots) {
786	      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
787	      for (const pr of wsResults.filter((r) => r.mergeable === false)) {
788	        const rebaseKey = `${pr.featureId}:${pr.taskId}`;
789	        if (rebaseInFlight.has(rebaseKey)) {
790	          emit({ type: "rebase_skipped_in_flight", task_id: pr.taskId, feature_id: pr.featureId });
791	          continue;
792	        }
793	        const rebaseTaskBranch = taskBranchName(pr.featureId, pr.taskId);
794	        const claimResult = claimRebase({
795	          workspaceRoot: wsRoot,
796	          featureId: pr.featureId,
797	          taskId: pr.taskId,
798	          taskBranch: rebaseTaskBranch,
799	          implBaseBranch: featureBranchName(pr.featureId),
800	          gitAuthorEmail,
801	          gitAuthorName,
802	          sshKeyPath,
803	          emit,
804	        });
805	        if (claimResult === "claim_lost") continue;
806	
807	        let rebaseTask: Task;
808	        try {
809	          rebaseTask = parseYaml(
810	            readFileSync(taskYamlAbsPath(wsRoot, pr.featureId, pr.taskId), "utf-8"),
811	          ) as Task;
812	        } catch (e) {
813	          emit({ type: "rebase_dispatch_read_error", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
814	          continue;
815	        }
816	        const { taskRepoUrl: rebaseImplUrl, taskBaseBranch: rebaseImplBase, implementationModel: rebaseModel } =
817	          resolveTaskContext(wsRoot, pr.featureId, rebaseTask);
818	        const rebaseMgmtCoords = parseManagementRepoCoords(wsRoot);
819	        const rebaseWsYaml = parseYaml(
820	          readFileSync(workspaceYamlPath(wsRoot), "utf-8"),
821	        ) as { workspace_id: string };
822	        // Result path uniqueness: same task can be re-dispatched after a failed
823	        // rebase, so suffix the path with a random slice (not the broker handle,
824	        // which is generated inside buildAndSubmitExecutor).
825	        const rebaseResultPath = join(tmpdir(), `rebase-result-${pr.taskId}-${randomUUID().slice(0, 8)}.json`);
826	        try {
827	          const rebaseHandle = await buildAndSubmitExecutor({
828	            task: rebaseTask,
829	            featureId: pr.featureId,
830	            workspaceId: rebaseWsYaml.workspace_id,
831	            taskRepoUrl: rebaseImplUrl,
832	            taskBranch: rebaseTaskBranch,
833	            // Rebase PR base is the feature branch (impl task PRs target it).
834	            taskBaseBranch: featureBranchName(pr.featureId),
835	            taskRepoBaseBranch: rebaseImplBase,
836	            mgmtRepoUrl: rebaseMgmtCoords.repoUrl,
837	            implementationModel: rebaseModel,
838	            resultPath: rebaseResultPath,
839	            workspaceLocalPath: wsRoot,
840	            kind: "rebase",
841	            prUrl: extractPrUrlFromTask(rebaseTask) ?? undefined,
842	          });
843	          rebaseInFlight.add(rebaseKey);
844	          outcome = "ran_task";
845	          emit({ type: "rebase_dispatched", task_id: pr.taskId, feature_id: pr.featureId, handle: rebaseHandle });
846	          if (runtimeProfile === "local-docker") dockerInFlight++;
847	        } catch (e) {
848	          emit({ type: "rebase_dispatch_failed", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
849	        }
850	      }
851	    }
852	
853	    for (const wsRoot of pulledWorkspaceRoots) {
854	      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
855	      if (wsResults.some((r) => r.merged === true)) {
856	        outcome = "ran_task";
857	        const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
858	        const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
859	        const mgmtCoords = parseManagementRepoCoords(wsRoot);
860	        try {
861	          await handleMergedPrs({
862	            prResults: wsResults,
863	            workspaceRoot: wsRoot,
864	            mgmtRepoOwner: mgmtCoords.owner,
865	            mgmtRepoName: mgmtCoords.repo,
866	            mgmtBaseBranch: mgmtCoords.baseBranch,
867	            githubToken,
868	            gitAuthorEmail,
869	            gitAuthorName,
870	            sshKeyPath,
871	            notifier: taskNotifier,
872	            emit,
873	            invokeClaudeForResolution: makeConflictResolver(conflictModel),
874	          });
875	        } catch (e) {
876	          emit({ type: "handle_merged_prs_error", workspace: wsRoot, details: String(e) });
877	        }
878	      }
879	    }
880	
881	    return outcome;
882	  }
