1007	      }
1008	    }
1009	  }
1010	
1011	  // ── Feature Reviewer Daemon (every FEATURE_REVIEW_INTERVAL cycles) ────────
1012	  async function featureReviewStep(pulledWorkspaceRoots: string[]): Promise<void> {
1013	    for (const wsRoot of pulledWorkspaceRoots) {
1014	      try {
1015	        const mgmtCoords = parseManagementRepoCoords(wsRoot);
1016	        await runFeatureReviewCycle({
1017	          workspaceRoot: wsRoot,
1018	          baseBranch: mgmtCoords.baseBranch,
1019	          mgmtRepoOwner: mgmtCoords.owner,
1020	          mgmtRepoName: mgmtCoords.repo,
1021	          githubToken,
1022	          reviewerGithubToken: process.env.REVIEWER_GITHUB_TOKEN,
1023	          gitAuthorEmail,
1024	          gitAuthorName,
1025	          sshKeyPath,
1026	          anthropicApiKey: process.env.ANTHROPIC_API_KEY,
1027	          slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
1028	          emit,
1029	        });
1030	      } catch (e) {
1031	        emit({ type: "feature_review_cycle_error", workspace: wsRoot, details: String(e) });
1032	      }
1033	    }
1034	  }
1035	
1036	  // ── State Invariant Checker (every N cycles) ──────────────────────────────
1037	  async function stateInvariantStep(pulledWorkspaceRoots: string[]): Promise<void> {
1038	    for (const wsRoot of pulledWorkspaceRoots) {
1039	      try {
1040	        await runStateInvariantCheck({
1041	          workspaceRoot: wsRoot,
1042	          githubToken,
1043	          gitAuthorEmail,
1044	          gitAuthorName,
1045	          sshKeyPath,
1046	          emit,
1047	        });
1048	      } catch (e) {
1049	        emit({ type: "state_invariant_check_error", workspace: wsRoot, details: String(e) });
1050	      }
1051	    }
1052	  }
1053	
1054	  // ── Shared reap loop ──────────────────────────────────────────────────────
1055	  async function reapStep(
1056	    pulledWorkspaceRoots: string[],
1057	    currentOutcome: CycleOutcome,
1058	  ): Promise<CycleOutcome> {
1059	    try {
1060	      const reapResult = await runReapLoop({
1061	        broker: ports.broker,
1062	        workspaceRoots: pulledWorkspaceRoots,
1063	        gitAuthorEmail,
1064	        gitAuthorName,
1065	        sshKeyPath,
1066	        githubToken,
1067	        emit,
1068	        rebaseInFlight,
1069	      });
1070	      if (reapResult.dispatched > 0) {
1071	        if (runtimeProfile === "local-docker") {
1072	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
1073	        }
1074	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
1075	        if (currentOutcome === "idle") return "ran_task";
1076	      }
1077	    } catch (e) {
1078	      emit({ type: "reap_loop_error", details: String(e) });
1079	    }
1080	    return currentOutcome;
1081	  }
1082	
1083	  // ── Poll cycle sequencer ──────────────────────────────────────────────────
1084	  async function runOneCycle(): Promise<CycleOutcome> {
1085	    const { haltedUrls, failedFeatureBranchMap } = await syncWorkspaces();
1086	
1087	    let outcome: CycleOutcome = "idle";
1088	    let pulledWorkspaceRoots: string[] = [];
1089	
1090	    // ── Subprocess concurrency guard + task dispatch ────────────────────────
1091	    // In local-subprocess mode all repos share the same container filesystem.
1092	    // Two concurrent subprocesses can race on git checkouts in the same repo.
1093	    // Wrap in a labeled block so we can break out (skipping to reap) when a
1094	    // subprocess is already in-flight.
1095	    dispatchBlock: {
1096	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
1097	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
1098	
1099	      if (runtimeProfile === "local-subprocess") {
1100	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
1101	        if (inFlight >= maxConcurrent) {
1102	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
1103	          break dispatchBlock;
1104	        }
1105	      } else if (runtimeProfile === "local-docker") {
1106	        if (dockerInFlight >= maxConcurrent) {
1107	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
1108	          break dispatchBlock;
1109	        }
1110	      }
1111	
1112	      ({ outcome, pulledWorkspaceRoots } = await claimStep(haltedUrls, failedFeatureBranchMap));
1113	
1114	      if (outcome !== "ran_task") {
1115	        outcome = await fixStep(haltedUrls);
1116	      }
1117	
1118	      if (githubToken && outcome !== "ran_task") {
1119	        outcome = await prPollStep(pulledWorkspaceRoots);
1120	      }
1121	
1122	      if (outcome !== "ran_task") {
1123	        outcome = await reviewerStep(haltedUrls);
1124	      }
1125	    } // end dispatchBlock
1126	
1127	    // ── Feature Notification Watcher ───────────────────────────────────────
1128	    await featureNotificationStep(pulledWorkspaceRoots);
1129	
1130	    // ── Feature-Tasks-Done checker ──────────────────────────────────────────
1131	    if (githubToken) {
1132	      await checkFeatureTasksDoneStep(pulledWorkspaceRoots);
1133	    }
1134	
1135	    // ── Feature Done Watcher ────────────────────────────────────────────────
1136	    if (githubToken) {
1137	      await featureDoneStep(pulledWorkspaceRoots);
1138	    }
1139	
1140	    // ── Feature Reviewer Daemon + State Invariant Checker ──────────────────
1141	    cycleCount++;
1142	    if (cycleCount % featureReviewInterval === 0) {
1143	      await featureReviewStep(pulledWorkspaceRoots);
1144	    }
1145	
1146	    if (cycleCount % stateInvariantCheckInterval === 0) {
1147	      await stateInvariantStep(pulledWorkspaceRoots);
1148	    }
1149	
1150	    // ── Shared reap loop ────────────────────────────────────────────────────
1151	    outcome = await reapStep(pulledWorkspaceRoots, outcome);
1152	
1153	    return outcome;
1154	  }
1155	
1156	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
1157	  return 0;
1158	}
1159	
1160	main()
1161	  .then((code) => process.exit(code))
1162	  .catch((e) => {
1163	    try {
1164	      console.log(JSON.stringify({
1165	        type: "fatal_error",
1166	        details: (e as Error).message ?? String(e),
1167	        at: new Date().toISOString(),
1168	      }));
1169	    } catch { /* last resort */ }
1170	    process.exit(4);
1171	  });
