/**
 * Orchestrator main entry point.
 *
 * Lifecycle:
 *   bootstrap (once) → polling loop:
 *     pull workspaces → eligibility → claim → briefing → adapter.run →
 *     side-effects → sleep → repeat
 *
 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
 *   0   → single-shot mode: one cycle then exit
 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
 *
 * Exit codes:
 *   0  normal exit
 *   2  agent.yaml invalid
 *   3  git clone/pull failed (bootstrap only)
 *   4  unexpected fatal error
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execSync, spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { runBootstrap } from "./bootstrap/bootstrap.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName, featureBranchName } from "./paths.js";
import { runFeatureBranchLifecycle } from "./feature-branch/lifecycle-manager.js";
import { findEligibleTasks, findFixableTasks, findReviewableTasks } from "./eligibility/match.js";
import { claimTask } from "./claim/claim-task.js";
import { claimFixTask } from "./claim/claim-fix-task.js";
import { openWorkspacePr } from "./claim/open-workspace-pr.js";
import type { Task, TaskLogEntry } from "./types/task.js";
import { extractPrUrlFromTask, normalizeTaskKeyOrder } from "./utils/task-yaml-io.js";
import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
import { resolveModel } from "./config/resolve-model-policy.js";
import { parseModelOverrides } from "./config/parse-model-overrides.js";
import {
  resolveRepoLocalPath,
  resolveRepoBaseBranch,
  resolveRepoGitUrl,
  loadWorkspaceModelPolicy,
  parseManagementRepoCoords,
  loadWorkspaceNotificationConfig,
} from "./config/workspace-config.js";
import { pullWorkspaces } from "./poll/pull-workspaces.js";
import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
import { runReapLoop } from "./poll/reap-loop.js";
import { checkInReviewPrs, type PrStatusResult } from "./poll/check-in-review-prs.js";
import { dispatchReviewer } from "./pr-response/dispatch-reviewer.js";
import { claimRebase } from "./pr-response/claim-rebase.js";
import { handleMergedPrs } from "./poll/handle-merged-prs.js";
import { taskNotifier } from "./adapters/slack-task-notifier.js";
import { handleFeatureDone } from "./poll/handle-feature-done.js";
import { checkFeatureTasksDone } from "./poll/check-feature-tasks-done.js";
import { ThreadedSlackNotifier, NullNotifier } from "./adapters/threaded-slack-notifier.js";
import { ThreadedNotificationService } from "./notifications/threaded-notification-service.js";
import { SlackWebApiClient } from "./slack/slack-web-api-client.js";
import { RedisThreadStore } from "./adapters/redis-thread-store.js";
import type { NotificationPort } from "./notifications/notification.port.js";
import {
  createFeatureNotificationState,
  runFeatureNotificationStep,
  type FeatureNotificationState,
} from "./feature-branch/feature-notification-watcher.js";
import { runFeatureReviewCycle } from "./poll/feature-review-cycle.js";
import { runStateInvariantCheck } from "./poll/state-invariant-checker.js";
import type { ExecutorPortInput } from "@workflow/runtime-abi";
import { buildGitEnv } from "./git-env.js";
import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
import { createLocalDockerProfile } from "./profiles/local-docker.js";
import { resolveExecutorBin, resolveExecutorEnv } from "./adapters/executor-factory.js";
import type { RuntimePorts } from "./runtime-ports.js";
import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
 * Passed to all conflict-resolution handlers so they respect workspace model_policy
 * instead of defaulting to whatever the Claude CLI ships with.
 */
function makeConflictResolver(
  model: string,
  maxTurns = 10,
): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
  return (prompt, cwd, env) =>
    new Promise((resolve) => {
      const child = spawn(
        "claude",
        [
          "-p", prompt,
          "--model", model,
          "--max-turns", String(maxTurns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
        ],
        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
      );
      child.stdout.pipe(process.stdout);
      child.stderr.pipe(process.stderr);
      child.on("close", (code) => resolve(code === 0));
      child.on("error", () => resolve(false));
    });
}

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required environment variable ${name} is not set`);
  return val;
}

function extractRepoName(url: string): string {
  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
  return match?.[1] ?? url;
}

/** Emit a structured JSON event via the profile's EventEmitterPort. */
function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
  return (event: Record<string, unknown>) => {
    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
    ports.emitter.emit(type ?? "event", data);
  };
}


interface TaskContext {
  taskRepoRoot: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  implementationModel: string;
}

function resolveTaskContext(
  workspaceLocalPath: string,
  featureId: string,
  task: Task,
): TaskContext {
  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);

  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
  let taskModelOverrides = {};
  try {
    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
  } catch { /* non-fatal */ }

  const implementationModel = resolveModel(
    workspaceModelPolicy,
    taskModelOverrides,
    "implementation",
    task.id,
  );

  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
}

/**
 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
 * Commits and pushes to the task branch. Throws on error.
 */
function writeRagPreFlight(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
  ragPreFlight: { query: string; injected: boolean; summary: string },
): void {
  const now = new Date().toISOString();
  const entry: TaskLogEntry = {
    action: "rag_pre_flight",
    by: gitAuthorEmail,
    at: now,
    rag_context_injected: ragPreFlight.injected,
    rag_summary: ragPreFlight.summary,
    rag_query: ragPreFlight.query,
    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
  };

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const gitOpts = {
    cwd: workspaceRoot,
    encoding: "utf-8" as const,
    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
    timeout: 30_000,
    stdio: "pipe" as const,
  };

  // Anchor to the task branch tip before reading/writing — same pattern as
  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
  // the task branch, but an explicit anchor makes this function self-contained.
  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);

  const task = normalizeTaskKeyOrder(parseYaml(readFileSync(yamlPath, "utf-8")) as Record<string, unknown>);
  task.log.push(entry);
  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  execSync(`git add "${relPath}"`, gitOpts);
  execSync(
    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
    gitOpts,
  );
  execSync(`git push origin "${taskBranch}"`, gitOpts);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<number> {
  let agentYamlPath: string;
  let workflowLocalPath: string;
  let workspacesRoot: string;
  let gitAuthorEmail: string;

  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
  const bootstrapEmit = (event: Record<string, unknown>) => {
    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
  };

  try {
    agentYamlPath = requireEnv("AGENT_YAML_PATH");
    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
    workspacesRoot = requireEnv("WORKSPACES_ROOT");
    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
  } catch (e) {
    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
    return 4;
  }

  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;

  const sshResolution = resolveSSHKey(process.env);
  const { sshKeyPath } = sshResolution;
  if (!sshKeyPath) {
    console.error("SSH_PRIVATE_KEY is not set — cannot perform git operations over SSH. Exiting.");
    return 1;
  }

  // ── Create the runtime profile ────────────────────────────────────────────────
  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
  // new infra is added without core changes.
  //   local-subprocess (default) — executor + in-process broker in one container
  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";

  // Resolved once at startup so buildAndSubmitExecutor can reuse the same path.
  // local-docker ignores this (ClaudeDockerRunAdapter selects the binary differently).
  const resolvedExecutorBinPath: string | undefined =
    runtimeProfile !== "local-docker"
      ? resolveExecutorBin(process.env.EXECUTOR_TYPE ?? "claude", {
          hermesModel: process.env.HERMES_INFERENCE_MODEL,
          hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
          deepseekApiKey: process.env.DEEPSEEK_API_KEY,
          ragMcpUrl: process.env.MCP_RAG_URL,
          hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
        })
      : undefined;

  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
    runtimeProfile === "local-docker"
      ? createLocalDockerProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
        })
      : (() => {
          const executorType = process.env.EXECUTOR_TYPE ?? "claude";
          const factoryConfig = {
            hermesModel: process.env.HERMES_INFERENCE_MODEL,
            hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
            deepseekApiKey: process.env.DEEPSEEK_API_KEY,
            ragMcpUrl: process.env.MCP_RAG_URL,
            hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
          };
          return createLocalSubprocessProfile({
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
            executor: {
              executorBinPath: resolvedExecutorBinPath,
              extraEnv: resolveExecutorEnv(executorType, factoryConfig),
            },
          });
        })();

  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
  const brokerPort = await ports.broker.start();

  const emit = makeEmit(ports);
  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });

  const bootstrapResult = await runBootstrap({ agentYamlPath });

  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;

  const config = bootstrapResult.config!;
  const githubToken = process.env.GITHUB_TOKEN ?? "";
  if (!githubToken) emit({ type: "warn_no_github_token" });

  // Local counter for local-docker mode — tracks how many executor containers are
  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
  let dockerInFlight = 0;
  // Tracks in-flight rebase executors by "featureId:taskId" key. Prevents duplicate
  // dispatch when the PR poll fires while a rebase executor is still running (docker
  // mode has no registrySize() guard equivalent for rebase tasks).
  const rebaseInFlight = new Set<string>();
  let cycleCount = 0;

  // ── Notification setup ────────────────────────────────────────────────────
  // Per-workspace notification ports keyed by workspaceRoot.
  const notificationPorts = new Map<string, NotificationPort>();
  // Per-workspace feature notification state (first-active-poll tracking).
  const featureNotificationStates = new Map<string, FeatureNotificationState>();

  /**
   * Build or return a cached NotificationPort for a given workspace.
   * Returns a NullNotifier when Slack or Redis config is absent.
   */
  function getOrBuildNotificationPort(wsRoot: string): NotificationPort {
    const cached = notificationPorts.get(wsRoot);
    if (cached) return cached;

    const slackToken = process.env.SLACK_BOT_TOKEN;
    const redisUrl = process.env.REDIS_URL;
    const notifConfig = loadWorkspaceNotificationConfig(wsRoot);

    let port: NotificationPort;
    if (slackToken && redisUrl && notifConfig?.slack.channelId) {
      const wsYaml = parseYaml(
        readFileSync(workspaceYamlPath(wsRoot), "utf-8"),
      ) as { workspace_id: string };
      const slackClient = new SlackWebApiClient({
        botToken: slackToken,
        channelId: notifConfig.slack.channelId,
      });
      const store = new RedisThreadStore(redisUrl);
      const service = new ThreadedNotificationService({
        slack: slackClient,
        store,
        workspaceId: wsYaml.workspace_id,
        emit: (e) => emit(e as Record<string, unknown>),
      });
      port = new ThreadedSlackNotifier(service);
      emit({ type: "threaded_slack_notifier_enabled", workspace: wsRoot });
    } else {
      port = new NullNotifier();
      emit({ type: "threaded_slack_notifier_disabled", workspace: wsRoot, reason: !slackToken ? "no_bot_token" : !redisUrl ? "no_redis_url" : "no_channel_id" });
    }

    notificationPorts.set(wsRoot, port);
    return port;
  }

  function getOrCreateFeatureNotificationState(wsRoot: string): FeatureNotificationState {
    if (!featureNotificationStates.has(wsRoot)) {
      featureNotificationStates.set(wsRoot, createFeatureNotificationState());
    }
    return featureNotificationStates.get(wsRoot)!;
  }
  const stateInvariantCheckInterval = parseInt(
    process.env.STATE_INVARIANT_CHECK_INTERVAL ?? "5",
    10,
  );
  const featureReviewInterval = parseInt(
    process.env.FEATURE_REVIEW_INTERVAL ?? "20",
    10,
  );

  async function buildAndSubmitExecutor(opts: {
    task: Task;
    featureId: string;
    workspaceId: string;
    taskRepoUrl: string;
    taskBranch: string;
    taskBaseBranch: string;
    taskRepoBaseBranch: string;
    mgmtRepoUrl: string;
    implementationModel: string;
    resultPath: string;
    workspaceLocalPath: string;
    /**
     * Briefing kind to dispatch with. Defaults to "impl" (fresh implementation or
     * blocked-recovery). "fix" → respond-to-review review-fixes mode.
     * "rebase" → respond-to-review conflict-resolution mode.
     */
    kind?: "impl" | "fix" | "rebase";
    /**
     * Implementation PR URL — passed to fix/rebase dispatches.
     */
    prUrl?: string;
    /**
     * The specific GitHub review event URL the fix agent should target.
     * Extracted by the caller from the most recent `reviewer_complete` log
     * entry. Set only for kind === "fix".
     */
    reviewUrl?: string;
  }) {
    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskBaseBranch,
            taskRepoBaseBranch, mgmtRepoUrl, implementationModel, resultPath,
            workspaceLocalPath, kind = "impl", prUrl, reviewUrl } = opts;

    const handle = randomUUID();
    const nonce = randomUUID();
    const callbackUrl = ports.broker.getCallbackUrl() ?? "";

    const execInput: ExecutorPortInput = {
      taskId: task.id,
      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch: taskBranch,
      taskBaseBranch,
      taskRepoBaseBranch,
      executorWorkdir: join(workspacesRoot, `exec-${handle}`),
      mgmtRepoUrl,
      resultPath,
      budgetTokens: config.budget.max_tokens_per_task,
      implementationModel,
      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
      githubToken,
      callbackUrl,
      nonce,
      // Broker `HandleKind` is decoupled from the orchestrator-internal `kind`
      // concept used for briefing routing. The reap loop branches:
      //   - kind="impl"      → dispatchExecutorResult (writes terminal_status to YAML)
      //   - kind="review-fix"→ emits review_dispatch_complete event ONLY (no YAML write)
      //   - kind="review"    → dispatchReviewResult
      //   - kind="rebase"    → conflict_state write
      // The fix agent's result has terminal_status: in_review|blocked and MUST
      // be written to YAML — so fix dispatches register as broker kind "impl"
      // (default). Only "rebase" needs an explicit override.
      //
      // Renaming the orchestrator-internal "fix" → ABI "review-fix" would route
      // fix results to the lightweight event branch and silently drop the YAML
      // write. Keep the abstractions separate.
      ...(kind === "rebase" ? { kind: "rebase" as const } : {}),
    };

    const extraEnv: Record<string, string> = {
      TASK_BRANCH: taskBranch,
      MAX_TURNS: String(config.budget.max_iterations),
      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
      KIND: kind,
      ...(prUrl && (kind === "fix" || kind === "rebase") ? { IMPL_PR_URL: prUrl } : {}),
      // MODE + REVIEW_URL for respond-to-review dispatch.
      // Fix dispatch → review-fixes mode + the specific review's URL.
      // Rebase dispatch → conflict-resolution mode (no review URL needed).
      ...(kind === "fix"    ? { MODE: "review-fixes",       ...(reviewUrl ? { REVIEW_URL: reviewUrl } : {}) } : {}),
      ...(kind === "rebase" ? { MODE: "conflict-resolution" } : {}),
    };

    const adapter =
      runtimeProfile === "local-docker"
        ? new (await import("./adapters/executor/claude-docker-run.js")).ClaudeDockerRunAdapter({
            broker: ports.broker,
            extraEnv,
            workspacesDir: workspacesRoot,
          })
        : new SubProcessAdapter({
            broker: ports.broker,
            executorBinPath: resolvedExecutorBinPath,
            extraEnv,
            workspacesDir: workspacesRoot,
          });

    return adapter.submit(execInput);
  }

  // ── Sync workspaces + feature branch lifecycle ────────────────────────────
  async function syncWorkspaces(): Promise<{
    haltedUrls: Set<string>;
    failedFeatureBranchMap: Map<string, Set<string>>;
  }> {
    // Skip impl repo pulls while an executor is in-flight.
    // syncRepo does `checkout <baseBranch> && reset --hard origin/<baseBranch>`,
    // which would switch the shared working tree away from the task branch and
    // wipe any uncommitted edits the executor made in the impl repo.
    const inFlightCount = ports.broker.inFlightCount?.() ?? 0;

    const pullResults = pullWorkspaces({
      watchUrls: config.watches,
      sshKeyPath,
      workspacesRoot,
      workflowUrl: process.env.WORKFLOW_URL,
      workflowLocalPath,
      emit,
      skipImplRepoPull: inFlightCount > 0,
    });

    const haltedUrls = new Set(
      pullResults
        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
        .map((r) => r.url),
    );

    const failedFeatureBranchMap = new Map<string, Set<string>>();
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;
      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      if (!existsSync(workspaceLocalPath)) continue;
      try {
        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
        const failed = runFeatureBranchLifecycle({
          workspaceRoot: workspaceLocalPath,
          baseBranch: mgmtCoords.baseBranch,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          githubToken: githubToken || undefined,
          repoOwner: mgmtCoords.owner,
          repoName: mgmtCoords.repo,
          slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
          emit,
        });
        if (failed.size > 0) {
          failedFeatureBranchMap.set(workspaceLocalPath, failed);
          emit({ type: "feature_branch_lifecycle_blocked", workspace: watchUrl, failed_features: [...failed] });
        }
      } catch (e) {
        emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
      }
    }

    return { haltedUrls, failedFeatureBranchMap };
  }

  // ── Claim step: scan ready tasks, claim + spawn executor ─────────────────
  async function claimStep(
    haltedUrls: Set<string>,
    failedFeatureBranchMap: Map<string, Set<string>>,
  ): Promise<{ outcome: CycleOutcome; pulledWorkspaceRoots: string[] }> {
    const pulledWorkspaceRoots: string[] = [];

    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      pulledWorkspaceRoots.push(workspaceLocalPath);

      if (!existsSync(workspaceLocalPath)) {
        emit({ type: "workspace_not_found", workspace_url: watchUrl });
        continue;
      }

      let eligibleTasks;
      try {
        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      if (eligibleTasks.length === 0) {
        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
        continue;
      }

      for (const { task, featureId } of eligibleTasks) {
        if (failedFeatureBranchMap.get(workspaceLocalPath)?.has(featureId)) {
          emit({ type: "task_skipped_feature_branch_failed", task_id: task.id, feature_id: featureId });
          continue;
        }

        const claimResult = await claimTask({
          workspaceRoot: workspaceLocalPath,
          taskId: task.id,
          featureId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          jitterMaxSeconds: config.jitter_max_seconds,
          // Task branches are seeded from and target the feature branch, not
          // the base branch — task PRs collect into the feature branch before
          // the Handoff Trigger merges the feature branch into the base.
          baseBranch: featureBranchName(featureId),
        });

        const taskBranch = taskBranchName(featureId, task.id);

        if (!claimResult.won) {
          if (claimResult.reason !== "branch_blocked_recovery") {
            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }
          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
        } else {
          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
        }

        // ── Open management-repo PR ─────────────────────────────────────────
        if (githubToken) {
          try {
            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
            await openWorkspacePr({
              workspaceRoot: workspaceLocalPath,
              featureId,
              taskId: task.id,
              branch: taskBranch,
              // Task PRs target the feature branch so all task changes collect
              // there before the Handoff Trigger merges to the base branch (T8).
              baseBranch: featureBranchName(featureId),
              githubToken,
              repoOwner: mgmtCoords.owner,
              repoName: mgmtCoords.repo,
              gitAuthorEmail,
              gitAuthorName,
              sshKeyPath,
            });
            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
          } catch (e) {
            const stderr = (e as { stderr?: Buffer | string }).stderr;
            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
          }
        }

        // ── Resolve model + task repo ───────────────────────────────────────
        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
          resolveTaskContext(workspaceLocalPath, featureId, task);

        // ── RAG pre-flight ──────────────────────────────────────────────────
        const mcpRagUrl = process.env.MCP_RAG_URL;
        const workspaceYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };
        const ragQuery = `${task.title} ${featureId}`;
        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);

        try {
          writeRagPreFlight(
            workspaceLocalPath,
            featureId,
            task.id,
            taskBranch,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
          );
        } catch (e) {
          const details = String(e);
          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
          mutateTaskYaml({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          continue;
        }


        // ── Submit executor (async — T6) ────────────────────────────────────
        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
        const execHandle = await buildAndSubmitExecutor({
          task, featureId, workspaceId: workspaceYaml.workspace_id,
          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
          mgmtRepoUrl: mgmtCoords.repoUrl, implementationModel,
          resultPath, workspaceLocalPath,
        });

        // Persist handle to task YAML for broker crash-recovery reconciliation.
        try {
          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
        } catch (e) {
          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
        }

        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
        if (runtimeProfile === "local-docker") dockerInFlight++;
        return { outcome: "ran_task", pulledWorkspaceRoots };
      }
    }
    return { outcome: "idle", pulledWorkspaceRoots };
  }

  // ── Fix step: scan change_requested tasks, claim + spawn fix executor ─────
  async function fixStep(haltedUrls: Set<string>): Promise<CycleOutcome> {
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      if (!existsSync(workspaceLocalPath)) continue;

      let fixableTasks;
      try {
        fixableTasks = findFixableTasks(config, workspaceLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      for (const { task, featureId } of fixableTasks) {
        const taskBranch = taskBranchName(featureId, task.id);
        const claimResult = await claimFixTask({
          workspaceRoot: workspaceLocalPath,
          taskId: task.id,
          featureId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          jitterMaxSeconds: config.jitter_max_seconds,
        });

        if (!claimResult.won) {
          emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason, details: claimResult.details });
          continue;
        }

        emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });

        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
        const fixWsYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };

        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
        const prUrl = extractPrUrlFromTask(task);
        // Find the most recent reviewer_complete log entry and pull its
        // review_url out. The orchestrator persists review_url on
        // change_requested mutations (dispatch-review-result.ts) so the fix
        // agent can target THIS specific review's inline comments rather
        // than fetching "all unresolved threads on the PR" (lossy across
        // multiple review cycles).
        const lastReviewerComplete = [...task.log]
          .reverse()
          .find((e) => e.action === "reviewer_complete");
        const reviewUrl =
          typeof lastReviewerComplete?.review_url === "string"
            ? lastReviewerComplete.review_url
            : undefined;
        emit({ type: "fix_executor_dispatch_started", task_id: task.id, feature_id: featureId, pr_url: prUrl, review_url: reviewUrl });
        const fixMgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
        const fixHandle = await buildAndSubmitExecutor({
          task, featureId, workspaceId: fixWsYaml.workspace_id,
          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
          mgmtRepoUrl: fixMgmtCoords.repoUrl, implementationModel,
          resultPath, workspaceLocalPath,
          kind: "fix",
          prUrl: prUrl ?? undefined,
          reviewUrl,
        });
        emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
        if (runtimeProfile === "local-docker") dockerInFlight++;
        return "ran_task";
      }
    }
    return "idle";
  }

  // ── PR poll step (5a): rebase conflicted PRs + handle merged PRs ──────────
  // Runs inside dispatchBlock so the subprocess guard prevents it from running
  // while an executor shares the container filesystem.
  async function prPollStep(pulledWorkspaceRoots: string[]): Promise<CycleOutcome> {
    let outcome: CycleOutcome = "idle";
    let prResults: PrStatusResult[] = [];
    try {
      ({ prResults } = await checkInReviewPrs({
        workspaceRoots: pulledWorkspaceRoots,
        githubToken,
        emit,
      }));
    } catch (e) {
      emit({ type: "in_review_poll_error", details: String(e) });
    }

    for (const wsRoot of pulledWorkspaceRoots) {
      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
      for (const pr of wsResults.filter((r) => r.mergeable === false)) {
        const rebaseKey = `${pr.featureId}:${pr.taskId}`;
        if (rebaseInFlight.has(rebaseKey)) {
          emit({ type: "rebase_skipped_in_flight", task_id: pr.taskId, feature_id: pr.featureId });
          continue;
        }
        const rebaseTaskBranch = taskBranchName(pr.featureId, pr.taskId);
        const claimResult = claimRebase({
          workspaceRoot: wsRoot,
          featureId: pr.featureId,
          taskId: pr.taskId,
          taskBranch: rebaseTaskBranch,
          implBaseBranch: featureBranchName(pr.featureId),
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          emit,
        });
        if (claimResult === "claim_lost") continue;

        let rebaseTask: Task;
        try {
          rebaseTask = parseYaml(
            readFileSync(taskYamlAbsPath(wsRoot, pr.featureId, pr.taskId), "utf-8"),
          ) as Task;
        } catch (e) {
          emit({ type: "rebase_dispatch_read_error", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
          continue;
        }
        const { taskRepoUrl: rebaseImplUrl, taskBaseBranch: rebaseImplBase, implementationModel: rebaseModel } =
          resolveTaskContext(wsRoot, pr.featureId, rebaseTask);
        const rebaseMgmtCoords = parseManagementRepoCoords(wsRoot);
        const rebaseWsYaml = parseYaml(
          readFileSync(workspaceYamlPath(wsRoot), "utf-8"),
        ) as { workspace_id: string };
        // Result path uniqueness: same task can be re-dispatched after a failed
        // rebase, so suffix the path with a random slice (not the broker handle,
        // which is generated inside buildAndSubmitExecutor).
        const rebaseResultPath = join(tmpdir(), `rebase-result-${pr.taskId}-${randomUUID().slice(0, 8)}.json`);
        try {
          const rebaseHandle = await buildAndSubmitExecutor({
            task: rebaseTask,
            featureId: pr.featureId,
            workspaceId: rebaseWsYaml.workspace_id,
            taskRepoUrl: rebaseImplUrl,
            taskBranch: rebaseTaskBranch,
            // Rebase PR base is the feature branch (impl task PRs target it).
            taskBaseBranch: featureBranchName(pr.featureId),
            taskRepoBaseBranch: rebaseImplBase,
            mgmtRepoUrl: rebaseMgmtCoords.repoUrl,
            implementationModel: rebaseModel,
            resultPath: rebaseResultPath,
            workspaceLocalPath: wsRoot,
            kind: "rebase",
            prUrl: extractPrUrlFromTask(rebaseTask) ?? undefined,
          });
          rebaseInFlight.add(rebaseKey);
          outcome = "ran_task";
          emit({ type: "rebase_dispatched", task_id: pr.taskId, feature_id: pr.featureId, handle: rebaseHandle });
          if (runtimeProfile === "local-docker") dockerInFlight++;
        } catch (e) {
          emit({ type: "rebase_dispatch_failed", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
        }
      }
    }

    for (const wsRoot of pulledWorkspaceRoots) {
      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
      if (wsResults.some((r) => r.merged === true)) {
        outcome = "ran_task";
        const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
        const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
        const mgmtCoords = parseManagementRepoCoords(wsRoot);
        try {
          await handleMergedPrs({
            prResults: wsResults,
            workspaceRoot: wsRoot,
            mgmtRepoOwner: mgmtCoords.owner,
            mgmtRepoName: mgmtCoords.repo,
            mgmtBaseBranch: mgmtCoords.baseBranch,
            githubToken,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
            notifier: taskNotifier,
            emit,
            invokeClaudeForResolution: makeConflictResolver(conflictModel),
          });
        } catch (e) {
          emit({ type: "handle_merged_prs_error", workspace: wsRoot, details: String(e) });
        }
      }
    }

    return outcome;
  }

  // ── Reviewer step (5b): dispatch reviewer agents ──────────────────────────
  // Only runs when 5a found no conflicts or merges this cycle.
  async function reviewerStep(haltedUrls: Set<string>): Promise<CycleOutcome> {
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      if (!existsSync(workspaceLocalPath)) continue;

      let reviewableTasks;
      try {
        reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      for (const { task, featureId } of reviewableTasks) {
        const taskBranch = taskBranchName(featureId, task.id);
        const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
        const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
        const revWsYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };
        let reviewModelOverrides = {};
        try {
          const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
          reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
        } catch { /* non-fatal */ }
        const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);

        const reviewerMgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
        const dispatchResult = await dispatchReviewer({
          workspaceRoot: workspaceLocalPath,
          featureId,
          taskId: task.id,
          taskBranch,
          implRepoRoot: taskRepoRoot,
          implRepoUrl: taskRepoUrl,
          mgmtRepoUrl: reviewerMgmtCoords.repoUrl,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          workflowLocalPath,
          maxTurns: config.budget.max_iterations,
          maxTokens: config.budget.max_tokens_per_task,
          logSinkEnabled: config.log_sink.enabled,
          reviewerModel,
          workspaceId: revWsYaml.workspace_id,
          broker: ports.broker,
          callbackUrl: ports.broker.getCallbackUrl() ?? "",
          emit,
        });

        if (dispatchResult === "dispatched") {
          if (runtimeProfile === "local-docker") dockerInFlight++;
          return "ran_task";
        }
      }
    }
    return "idle";
  }

