  // ── Shared reap loop ──────────────────────────────────────────────────────
  async function reapStep(
    pulledWorkspaceRoots: string[],
    currentOutcome: CycleOutcome,
  ): Promise<CycleOutcome> {
    try {
      const reapResult = await runReapLoop({
        broker: ports.broker,
        workspaceRoots: pulledWorkspaceRoots,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        githubToken,
        emit,
        rebaseInFlight,
      });
      if (reapResult.dispatched > 0) {
        if (runtimeProfile === "local-docker") {
          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
        }
        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
        if (currentOutcome === "idle") return "ran_task";
      }
    } catch (e) {
      emit({ type: "reap_loop_error", details: String(e) });
    }
    return currentOutcome;
  }

  // ── Poll cycle sequencer ──────────────────────────────────────────────────
  async function runOneCycle(): Promise<CycleOutcome> {
    const { haltedUrls, failedFeatureBranchMap } = await syncWorkspaces();

    let outcome: CycleOutcome = "idle";
    let pulledWorkspaceRoots: string[] = [];

    // ── Subprocess concurrency guard + task dispatch ────────────────────────
    // In local-subprocess mode all repos share the same container filesystem.
    // Two concurrent subprocesses can race on git checkouts in the same repo.
    // Wrap in a labeled block so we can break out (skipping to reap) when a
    // subprocess is already in-flight.
    dispatchBlock: {
      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;

      if (runtimeProfile === "local-subprocess") {
        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
        if (inFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      } else if (runtimeProfile === "local-docker") {
        if (dockerInFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      }

      ({ outcome, pulledWorkspaceRoots } = await claimStep(haltedUrls, failedFeatureBranchMap));

      if (outcome !== "ran_task") {
        outcome = await fixStep(haltedUrls);
      }

      if (githubToken && outcome !== "ran_task") {
        outcome = await prPollStep(pulledWorkspaceRoots);
      }

      if (outcome !== "ran_task") {
        outcome = await reviewerStep(haltedUrls);
      }
    } // end dispatchBlock

    // ── Feature Notification Watcher ───────────────────────────────────────
    await featureNotificationStep(pulledWorkspaceRoots);

    // ── Feature-Tasks-Done checker ──────────────────────────────────────────
    if (githubToken) {
      await checkFeatureTasksDoneStep(pulledWorkspaceRoots);
    }

    // ── Feature Done Watcher ────────────────────────────────────────────────
    if (githubToken) {
      await featureDoneStep(pulledWorkspaceRoots);
    }

    // ── Feature Reviewer Daemon + State Invariant Checker ──────────────────
    cycleCount++;
    if (cycleCount % featureReviewInterval === 0) {
      await featureReviewStep(pulledWorkspaceRoots);
    }

    if (cycleCount % stateInvariantCheckInterval === 0) {
      await stateInvariantStep(pulledWorkspaceRoots);
    }

    // ── Shared reap loop ────────────────────────────────────────────────────
    outcome = await reapStep(pulledWorkspaceRoots, outcome);

    return outcome;
  }

  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
  return 0;
}

main()
  .then((code) => process.exit(code))
  .catch((e) => {
    try {
      console.log(JSON.stringify({
        type: "fatal_error",
        details: (e as Error).message ?? String(e),
        at: new Date().toISOString(),
      }));
    } catch { /* last resort */ }
    process.exit(4);
  });

